/**
 * @brief 递归检查二叉树是否为二分搜索树
 * @param node 当前节点
 * @param prev 用于记录前一个节点的指针，确保当前节点值大于前一个节点值
 * @return 如果是二分搜索树返回 true，否则返回 false
 */
static bool bst_check(const TreeNode* node, const TreeNode*& prev) {
    if (!node) return true;  // 空节点，合法

    // 递归检查左子树
    if (!bst_check(node->left, prev)) return false;

    // 检查当前节点是否大于前一个节点
    if (prev && prev->value >= node->value) return false;
    prev = node;  // 更新前一个节点为当前节点

    // 递归检查右子树
    return bst_check(node->right, prev);
}

/**
 * @brief 验证一棵二叉树是否为二分搜索树
 * @param root 根节点
 * @throws std::invalid_argument 如果不是二分搜索树
 */
static void validate_bst(const TreeNode* root) {
    const TreeNode* prev = nullptr;
    if (!bst_check(root, prev)) {
        throw std::invalid_argument("不满足二分搜索树性质");
    }
}

/**
