 * @param root 根节点
 * @param value 要插入的值
 * @return 新的根节点
 * @throws std::invalid_argument 如果值已存在
 */
TreeNode* bst_insert(TreeNode* root, int value) {
    validate_bst(root);  // 插入前先验证树的合法性

    if (!root) {
        return new TreeNode{value, nullptr, nullptr};  // 空树，直接创建新节点
    }

    if (value == root->value) {
        throw std::invalid_argument("二分搜索树不允许重复值");
    }

    if (value < root->value) {
        // 插入到左子树，并更新左子树的根节点
        return new TreeNode{root->value, bst_insert(root->left, value), root->right};
    } else {
        // 插入到右子树，并更新右子树的根节点
        return new TreeNode{root->value, root->left, bst_insert(root->right, value)};
    }
}

