        // 如果最大值是当前节点，说明已经是最小堆结构，无需调整
        if (largest == index) {
            break;
        }

        // 交换当前节点与最大值节点
        std::swap(heap[index], heap[largest]);

        // 继续下滤
        index = largest;
    }
}

